#!/usr/bin/env python3
"""Standalone equipment and socket review. Never runs the game or touches saves."""
from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]
files=re.findall(r'<script src="([^"]+)"', (root/'index.html').read_text())
files=files[:files.index('src/game/05-ui.js')]
html='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Y2K 專裝模型預覽</title><style>body{margin:0;background:#dfe5ee;color:#172751;font:16px/1.6 system-ui,sans-serif}main{max-width:1100px;padding:16px;margin:auto}h1{font-size:24px;margin:0}button,select{font:inherit;min-height:44px;padding:6px 12px;margin:4px;border:1px solid #7b8ba4;color:inherit;background:#f2f4f7}canvas{width:100%;height:65vh;display:block;background:#c1cddc}#status{min-height:28px}</style><main><h1>Y2K 專裝模型預覽</h1><p>獨立預覽，不讀寫存檔。左邊是角色實際裝備位置，右邊可旋轉查看原模型。未提供 3D 的參考項目先以簡模顯示。</p><select id="gear" aria-label="選擇專裝"></select><button id="rotate">旋轉模型</button><button id="motion">播放攻擊</button><button id="plain">普通裝備替代模型</button><canvas id="view" aria-label="裝備 3D 預覽"></canvas><p id="status" role="status"></p></main>'''
for f in files:html+='<script>\n'+(root/f).read_text()+'\n</script>'
html+='''<script>
(()=>{const canvas=document.getElementById('view'),status=document.getElementById('status'),select=document.getElementById('gear'),rd=new T3.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true});rd.outputColorSpace=T3.SRGBColorSpace;rd.setPixelRatio(Math.min(devicePixelRatio,1.5));const scene=new T3.Scene();scene.background=new T3.Color('#c1cddc');scene.add(new T3.HemisphereLight(0xeaf5ff,0x6f7c89,2));const sun=new T3.DirectionalLight(0xfff6ed,2);sun.position.set(30,60,70);scene.add(sun);const cam=new T3.OrthographicCamera(-37,37,38,-4,.1,200);cam.position.set(0,18,90);cam.lookAt(0,18,0);let hero,item,rotating=false,yaw=.1,attacking=false;
for(const spec of Object.values(SIGNATURE_GEAR)){const o=document.createElement('option');o.value=spec.id;o.textContent=spec.name+(EQUIPMENT_GLB[spec.model]?'':'（待補 3D）');select.appendChild(o);}
function choose(id){if(hero){characterDispose(hero);scene.remove(hero);}if(item)scene.remove(item);G.equip={weapon:null,armor:null,ring:null};const spec=SIGNATURE_GEAR[id];G.char=spec?.owner||'street';if(spec)G.equip[spec.slot]=makeItem(spec.slot,3,15,id);else for(const slot of Object.keys(SLOTN))G.equip[slot]=makeItem(slot,1,8);hero=buildY2KHero(0,0,0,0,{});hero.scale.setScalar(1);hero.position.x=-13;scene.add(hero);item=spec?equipmentModel(spec.model):buildSimpleEquipment('weapon',0,1);if(!item)item=buildSimpleEquipment(spec.slot,0,3);item.scale.setScalar(spec&&EQUIPMENT_GLB[spec.model]?15:1);item.position.set(13,16,0);scene.add(item);status.textContent=spec?spec.name+'｜'+SLOTN[spec.slot]+'｜'+(EQUIPMENT_GLB[spec.model]?'已接入上傳模型':'僅有參考圖，暫用簡模'):'普通裝備暫用簡單幾何模型';select.value=id||'';}
select.onchange=()=>choose(select.value);document.getElementById('rotate').onclick=()=>rotating=!rotating;document.getElementById('motion').onclick=()=>attacking=!attacking;document.getElementById('plain').onclick=()=>choose(null);window.EQUIPMENT_REVIEW={choose,renderer:rd,scene,get hero(){return hero;},get item(){return item;}};choose(select.value);let last=performance.now();function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;const w=canvas.clientWidth,h=canvas.clientHeight;rd.setSize(w,h,false);cam.left=-21*w/h;cam.right=21*w/h;cam.top=21;cam.bottom=-21;cam.updateProjectionMatrix();if(rotating)yaw+=dt*.5;hero.rotation.y=yaw;item.rotation.y=yaw;characterAnimate(hero,dt,{attack:attacking,swing:(now/1000)%.6});rd.render(scene,cam);requestAnimationFrame(frame);}requestAnimationFrame(frame);
})();
</script></html>'''
(root/'dist/equipment-review.html').write_text(html)
print('wrote dist/equipment-review.html')
